INSERT INTO restaurants (id, name, description, cuisine, address, city, phone, image_url, rating, price_tier, opening_time, closing_time, total_tables) VALUES
('rest-in-01', 'Bukhara - ITC Maurya', 'Legendary clay tandoor culinary marvel crafted over 40 years, serving iconic Dal Bukhara and melt-in-mouth kebabs in New Delhi.', 'North Indian', 'Diplomatic Enclave, Chanakyapuri', 'New Delhi', '+91-11-2611-2233', 'https://images.unsplash.com/photo-1585937421612-70a008356fbe?auto=format&fit=crop&w=800&q=80', 4.9, '₹₹₹₹', '12:30', '23:45', 12),
('rest-in-02', 'Saravanaa Bhavan', 'World-renowned South Indian pure vegetarian culinary heritage with golden crisp dosas, idlis, and traditional brass-tumbler filter coffee.', 'South Indian', '19 Kennet Lane, Egmore', 'Chennai', '+91-44-2819-1234', 'https://images.unsplash.com/photo-1668236543090-82eba5ee5976?auto=format&fit=crop&w=800&q=80', 4.8, '₹', '07:00', '22:30', 14),
('rest-in-03', 'Paradise Biryani', 'The world-famous heart of authentic Hyderabadi Dum Biryani cooked with aged long-grain Basmati, saffron, and tender spices since 1953.', 'Biryani & Mughlai', 'MG Road, Secunderabad', 'Hyderabad', '+91-40-6666-5588', 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80', 4.8, '₹₹', '11:30', '23:30', 16),
('rest-in-04', 'Trishna Coastal Dining', 'Celebrated Mumbai seafood institution famous for fresh Butter Garlic Crab, Mangalorean fish curries, and warm Neer Dosas.', 'Coastal Seafood', '7 Sai Baba Marg, Kala Ghoda, Fort', 'Mumbai', '+91-22-2270-3213', 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?auto=format&fit=crop&w=800&q=80', 4.9, '₹₹₹₹', '12:00', '23:45', 10),
('rest-in-05', 'Karavalli - The Gateway Hotel', 'Award-winning sanctuary celebrating traditional coastal home-cooking from Mangalore, Goa, and Kerala in a heritage Bengaluru courtyard.', 'South Indian', '66 Residency Road', 'Bengaluru', '+91-80-6660-4545', 'https://images.unsplash.com/photo-1610057099431-d73a1c9d2f2f?auto=format&fit=crop&w=800&q=80', 4.9, '₹₹₹₹', '12:30', '23:30', 10),
('rest-in-06', 'Peter Cat', 'Iconic Park Street landmark with dim vintage chandeliers, legendary Iranian Cheelo Kebabs, and classic sizzlers loved across generations.', 'Continental & North Indian', '18A Park Street', 'Kolkata', '+91-33-2229-8841', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80', 4.7, '₹₹', '11:00', '23:15', 12),
('rest-in-07', 'Chokhi Dhani Ethnic Village', 'Immersive Rajasthani cultural dining experience featuring unlimited royal thalis with Dal Baati Churma, Gatte Ki Sabzi, and Malpuas.', 'Rajasthani & Thali', '12 Miles, Tonk Road', 'Jaipur', '+91-141-516-5000', 'https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=800&q=80', 4.8, '₹₹₹', '17:30', '23:30', 16),
('rest-in-08', 'Britto''s Shack & Bar', 'Quintessential beachfront shack on Baga Beach serving Goan Prawn Curries, Chicken Xacuti, Pork Vindaloo, and chilled beverages with sea breeze.', 'Coastal Seafood', 'Baga Beach, Calangute, North Goa', 'Goa', '+91-832-227-7331', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', 4.6, '₹₹', '09:00', '00:30', 15),
('rest-in-09', 'Gulati Restaurant', 'Celebrated culinary destination on Pandara Road renowned for Delhi’s richest Butter Chicken, Dal Makhani, and Kakori kebabs.', 'North Indian', '6 Pandara Road Market', 'New Delhi', '+91-11-2338-8836', 'https://images.unsplash.com/photo-1565557623262-b51c2513a641?auto=format&fit=crop&w=800&q=80', 4.9, '₹₹₹', '12:00', '00:00', 14),
('rest-in-10', 'The Fatty Bao', 'Vibrant rooftop Asian gastro-bar in Indiranagar famous for pillowy open baos, artisan dim sums, ramen bowls, and innovative cocktails.', 'Pan-Asian', '610 12th Main Rd, HAL 2nd Stage, Indiranagar', 'Bengaluru', '+91-80-4124-2434', 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=800&q=80', 4.8, '₹₹₹', '12:00', '23:30', 10),
('rest-in-11', 'Gajalee Seafood', 'Unrivaled Maharashtrian Malvani seafood dining serving charcoal tandoori bombil, crab sukka, and refreshing Sol Kadhi.', 'Coastal Seafood', 'Kadam Marg, Vile Parle East', 'Mumbai', '+91-22-2611-4093', 'https://images.unsplash.com/photo-1559847844-5315695dadae?auto=format&fit=crop&w=800&q=80', 4.8, '₹₹₹', '11:30', '23:45', 11),
('rest-in-12', 'Bawarchi Restaurant', 'Crowd-favorite Hyderabadi culinary institution at RTC X Roads dishing out flavorful Dum Biryanis, Tangdi Kebabs, and Rumali Rotis.', 'Biryani & Mughlai', 'Beside Sandhya Theatre, RTC X Roads', 'Hyderabad', '+91-40-2763-4490', 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=800&q=80', 4.7, '₹₹', '11:30', '23:45', 18),
('rest-in-13', 'Murugan Idli Shop', 'Beloved Chennai breakfast tradition known for cloud-soft steamed idlis, ghee onion uthappams, and Madurai special Jigarthanda.', 'South Indian', 'GN Chetty Road, T. Nagar', 'Chennai', '+91-44-2815-5444', 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?auto=format&fit=crop&w=800&q=80', 4.8, '₹', '06:30', '23:00', 15),
('rest-in-14', '6 Ballygunge Place', 'Pristine colonial mansion preserving authentic Bengali royal heritage with Kosha Mangsho, Daab Chingri, Bhetki Paturi, and Baked Mishti Doi.', 'Bengali', '6 Ballygunge Place, Ballygunge', 'Kolkata', '+91-33-2460-3922', 'https://images.unsplash.com/photo-1605197148564-90ef59ef6e4d?auto=format&fit=crop&w=800&q=80', 4.8, '₹₹₹', '12:00', '22:30', 10),
('rest-in-15', 'Smoke House Deli', 'Artisanal European cafe in Bandra featuring hand-rolled pastas, truffle risottos, sourdough pizzas, and gourmet desserts.', 'Italian & Continental', 'Madhu Milan Building, 33rd Road, Bandra West', 'Mumbai', '+91-22-6528-7800', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 4.7, '₹₹₹', '09:00', '23:30', 12),
('rest-in-16', 'Agashiye - The House of MG', 'Rooftop Gujarati fine dining in a 1924 heritage boutique hotel serving traditional seasonal thalis, undhiyu, and fresh basundi.', 'Rajasthani & Thali', 'Opposite Sidi Saiyyed Mosque, Lal Darwaja', 'Ahmedabad', '+91-79-2550-6946', 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?auto=format&fit=crop&w=800&q=80', 4.9, '₹₹₹', '12:00', '23:00', 14),
('rest-in-17', 'Farzi Cafe', 'Trendsetting modern Indian bistro in Cyber Hub pioneering culinary illusions, molecular gastronomy, and global Indian comfort food.', 'Modern Indian', 'Cyber Hub, DLF Phase 2, Gurugram', 'Delhi NCR', '+91-124-492-2273', 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=800&q=80', 4.8, '₹₹₹', '12:00', '00:00', 14),
('rest-in-18', 'Haldiram''s Royale', 'Beloved Old Delhi street food and chaat destination serving legendary Chhole Bhature, Raj Kachoris, Pav Bhaji, and hot Gulab Jamuns.', 'Street Food & Chaat', '1454 Chandni Chowk, Old Delhi', 'New Delhi', '+91-11-4770-5555', 'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?auto=format&fit=crop&w=800&q=80', 4.7, '₹', '09:00', '22:30', 16);
